import { Label, Node, sp, tween, Tween, UIOpacity } from "cc";
import StoreManager from "../store/StoreManager";
import AppAnimation from "../ui/AppAnimation";

/**
 * WinBarController（中獎累計條 / 倍率演出全家族）
 *
 * 1001/1002 逐字相同，只有 View 具體型別不同。負責：
 * - 中獎累計數字：setWinBarNum 直接設值、addWinBarScore 用 tween 從當前值滾到目標值、
 *   playWinBarAdd 播放 add spine 動效後延遲寫入最終值、resetWinBar 歸零並清空 spine。
 * - 倍率顯示（mul）：showWinBarMul 依是否已進場播放 mul/mul2 動效並淡入。
 * - FG 累積倍率計數器（frame_total_multiplier）：setTotalMultiplierLabel 更新文字並觸發
 *   彈跳 + ui_mul 動效。
 * - rollWinBalance：玩家餘額欄位的捲動動畫（非中獎條本身，是 TemplateStore.winBalance）。
 */

/** WinBarController 只需要用到的 View 子集合，各遊戲自己的 GameViewAdapter 結構相容即可傳入 */
export interface WinBarView {
    bg: Node | null;
    /** 中獎累計條根節點 */
    winBarNode: Node | null;
    /** 中獎累計條 spine */
    winBarSkel: sp.Skeleton | null;
    /** 中獎累計數字 Label */
    winBarNumLabel: Label | null;
    /** 倍率節點（mul） */
    winBarMulNode: Node | null;
    /** 倍率 Label */
    winBarMulLabel: Label | null;
    /** 倍率節點 UIOpacity（mul 常駐 opacity 動畫用） */
    winBarMulOpacity?: UIOpacity | null;
    /** FG 累積倍率計數器 Label（frame_total_multiplier） */
    frameTotalMultiplierLabel: Label | null;
    /** FG 累積倍率計數器變動時的 spine 動效（ui_mul） */
    frameTotalMultiplierSpine?: sp.Skeleton | null;
}

export interface WinBarDeps {
    getViews: () => WinBarView[];
    storeManager: StoreManager;
    /** 傳入 GameMain 自己的 Component.scheduleOnce，保留原本的元件生命週期安全性 */
    scheduleOnce: (callback: Function, delay?: number) => void;
}

/** win bar 演出全家族：1001/1002 逐字相同，只有 View 具體型別不同 */
export class WinBarController {
    winBarValue = 0;
    winBarProxy = { v: 0 };
    winBarMulValue = 0;
    winBarMulEntered = false;

    private rollActive = false;
    private rollFrom = 0;
    private rollTarget = 0;
    private rollElapsed = 0;
    private rollDuration = 0;
    private rollResolve: (() => void) | null = null;

    /**
     * @param deps 取得 View、store 與排程的依賴集合。
     */
    constructor(private deps: WinBarDeps) { }

    /**
     * 取得（必要時補掛）倍率節點上的 UIOpacity。
     *
     * @param v 目標 View。
     * @returns UIOpacity；該 View 沒有倍率節點時是 null。
     */
    private ensureMulOpacity(v: WinBarView): UIOpacity | null {
        return v.winBarMulOpacity ?? v.winBarMulNode?.getComponent(UIOpacity) ?? v.winBarMulNode?.addComponent(UIOpacity) ?? null;
    }

    /**
     * 直接寫入贏分條的數字（不播演出），格式依目前幣別。
     *
     * @param val 數字。
     */
    setWinBarNum(val: number): void {
        const s = this.deps.storeManager.getGameStore().formatAmount(val);
        for (const v of this.deps.getViews()) {
            if (v.winBarNumLabel) v.winBarNumLabel.string = s;
        }
    }

    /**
     * 把贏分條與倍率整組歸零，並停掉進行中的跑分 tween。
     *
     * tween 一定要先停：不停的話它下一幀還會把舊的目標值寫回去，看起來像歸零失敗。
     */
    resetWinBar(): void {
        Tween.stopAllByTarget(this.winBarProxy);
        this.winBarValue = 0;
        this.winBarProxy.v = 0;
        this.winBarMulValue = 0;
        this.winBarMulEntered = false;
        this.setWinBarNum(0);
        for (const v of this.deps.getViews()) {
            if (v.winBarMulNode) v.winBarMulNode.active = false;
            if (v.winBarSkel) {
                v.winBarSkel.clearTracks();
                v.winBarSkel.setToSetupPose();
            }
        }
    }

    /**
     * 直接寫入倍率文字（不播演出）。
     *
     * @param val 倍率。
     */
    setWinBarMul(val: number): void {
        for (const v of this.deps.getViews()) {
            if (v.winBarMulLabel) v.winBarMulLabel.string = `x${val}`;
        }
    }

    /**
     * 顯示倍率並播進場演出；第二次之後改播 `mul2`（比較短的版本）。
     *
     * @param val 倍率。
     * @param _isFg 保留參數，目前橫直版共用同一套演出。
     */
    showWinBarMul(val: number, _isFg: boolean): void {
        this.setWinBarMul(val);
        const anim = this.winBarMulEntered ? 'mul2' : 'mul';
        for (const v of this.deps.getViews()) {
            if (v.winBarMulNode) {
                v.winBarMulNode.active = true;
                const uo = this.ensureMulOpacity(v);
                if (uo) {
                    Tween.stopAllByTarget(uo);
                    uo.opacity = 255;
                }
            }
            v.winBarSkel?.setAnimation(0, anim, false);
        }
        this.winBarMulEntered = true;
    }

    /**
     * 播贏分條的加分演出，並把倍率節點淡回全不透明。
     *
     * @param finalNum 加完之後的數字。
     */
    playWinBarAdd(finalNum: number): void {
        for (const v of this.deps.getViews()) {
            v.winBarSkel?.setAnimation(0, 'add', false);
            const uo = this.ensureMulOpacity(v);
            if (uo) {
                Tween.stopAllByTarget(uo);
                uo.opacity = 255;
                tween(uo).delay(0.2).to(0.13, { opacity: 0 }).start();
            }
        }
        this.deps.scheduleOnce(() => {
            this.winBarValue = finalNum;
            this.setWinBarNum(finalNum);
        }, 0.47);
    }

    /**
     * 把一筆贏分累加進贏分條，用 0.3 秒 tween 跑到新的總和；delta 不是正數時直接略過。
     *
     * @param delta 這次要加上去的分數。
     */
    addWinBarScore(delta: number): void {
        if (delta <= 0) return;
        this.winBarValue += delta;
        const to = this.winBarValue;
        Tween.stopAllByTarget(this.winBarProxy);
        tween(this.winBarProxy)
            .to(0.3, { v: to }, { onUpdate: () => this.setWinBarNum(this.winBarProxy.v) })
            .call(() => this.setWinBarNum(to))
            .start();
    }

    /** 設定 FG 累積倍率計數器（frame_total_multiplier > Label）顯示 `{acc}x`，同時觸發彈跳與 ui_mul 動效 */
    setTotalMultiplierLabel(acc: number): void {
        for (const v of this.deps.getViews()) {
            if (v.frameTotalMultiplierLabel) {
                v.frameTotalMultiplierLabel.string = `${acc}x`;
                AppAnimation.playBounce(v.frameTotalMultiplierLabel.node);
            }
            const spine = v.frameTotalMultiplierSpine;
            if (spine) {
                spine.node.active = true;
                spine.setAnimation(0, 'animation', false);
                spine.setCompleteListener(() => {
                    spine.setCompleteListener(null!);
                    spine.node.active = false;
                });
            }
        }
    }

    // 用 dt 累加 不用固定間隔 setTimeout 累加寫法能吃到 director hook 的加速縮放
    /**
     * 每幀推進餘額捲動；沒有在捲動時直接返回。
     *
     * 用 dt 累加而不是 tween，是為了吃得到 director hook 的整體加速縮放。
     *
     * @param dt 距離上一幀的秒數。
     */
    update(dt: number): void {
        if (!this.rollActive) return;
        this.rollElapsed += dt;
        const ratio = this.rollDuration <= 0 ? 1 : Math.min(this.rollElapsed / this.rollDuration, 1);
        const templateStore = this.deps.storeManager.getModel('TemplateStore');
        templateStore.setWinBalance(Number((this.rollFrom + (this.rollTarget - this.rollFrom) * ratio).toFixed(2)));
        if (ratio >= 1) {
            this.rollActive = false;
            const resolve = this.rollResolve;
            this.rollResolve = null;
            resolve?.();
        }
    }

    /**
     * 把玩家餘額從目前值捲動到目標值。重複呼叫會取消上一次。
     *
     * @param to 目標金額。
     * @param duration 捲動秒數；0 以下代表立刻跳到目標值。
     * @returns 捲完之後 resolve。
     */
    rollWinBalance(to: number, duration: number): Promise<void> {
        this.rollActive = false;
        const templateStore = this.deps.storeManager.getModel('TemplateStore');
        this.rollFrom = Number(templateStore.winBalance) || 0;
        this.rollTarget = Number(to.toFixed(2));
        this.rollDuration = duration;
        this.rollElapsed = 0;

        return new Promise<void>((resolve) => {
            if (duration <= 0) {
                templateStore.setWinBalance(this.rollTarget);
                resolve();
                return;
            }
            this.rollResolve = resolve;
            this.rollActive = true;
        });
    }
}
