import AppAudio from '../audio/AppAudio';
import { GameState } from './GameState';
import { GameStateKey } from './GameStateKey';
import type { GameMain_1003 } from '../GameMain_1003';
import { MUSICMAP } from '../audio/AudioConfig';

/**
 * 一般局狀態（比照舊專案 SGState_NG，本體維持空殼——實際的進場/離場 side effect
 * 由 EnterFreeGameTask/ExitFreeGameTask 負責，changeState() 只是流程中的一步）。
 */
export class NGState_1003 extends GameState<GameMain_1003> {
    /** 進入主遊戲狀態時套用對應的介面與背景。 */
    protected override onEnter(): void {
        const audio = AppAudio.getInstance();
        audio.stopMusic();
        audio.playMusic(MUSICMAP.BGM, 0);
        audio.playMusic(MUSICMAP.BACKGROUND, 1);

        // 存進 GameStore.gameMode
        this.game.storeManager.getGameStore().setGameMode(GameStateKey.NG);
    }
}
