import type { SlotApiBetDetailResponse, SlotApiBetHistoryItem, SlotApiBetHistoryResponse } from './SlotApiTypes';
import type { BetHistoryDetail, BetHistoryPage, BetHistorySummary } from '../models/BetHistory';
import type { SlotGridLayout } from '../models/SlotGrid';
import { SlotRoundMapper } from './SlotRoundMapper';

/** GET_BET_HISTORY／GET_BET_DETAIL response 到 BetHistoryPage／BetHistoryDetail 的唯一轉換點 */
export class SlotHistoryMapper {
    private readonly roundMapper: SlotRoundMapper;

    /**
     * @param layout 解析歷史盤面時要用的盤面形狀。
     */
    constructor(layout: SlotGridLayout) {
        this.roundMapper = new SlotRoundMapper(layout);
    }

    /**
     * 把後端的投注紀錄回應轉成前端的分頁結構。
     *
     * @param response 投注紀錄回應。
     * @returns 分頁結構。
     */
    toBetHistoryPage(response: SlotApiBetHistoryResponse): BetHistoryPage {
        return {
            items: (response.items ?? []).map((item) => this.toBetHistorySummary(item)),
            hasMore: response.has_more ?? false,
            nextCursor: response.next_cursor,
        };
    }

    /**
     * 把後端的單筆明細轉成前端結構。
     *
     * 贏分欄位在新舊版回應裡的位置不同，這裡逐層 fallback 取值。
     *
     * @param response 明細回應。
     * @returns 明細結構。
     */
    toBetHistoryDetail(response: SlotApiBetDetailResponse): BetHistoryDetail {
        return {
            engineWin: response.engine_win ?? response.summary.engine_win ?? response.summary.win_amount,
            rawEngineWin: response.raw_engine_win ?? response.summary.raw_engine_win ?? response.summary.win_amount,
            summary: this.toBetHistorySummary(response.summary),
            rngUsedJson: response.rng_used_json,
            ...this.roundMapper.toRoundSteps(response.round_result),
        };
    }

    /**
     * 把單筆紀錄的摘要欄位轉成前端命名。
     *
     * @param item 後端的單筆紀錄。
     * @returns 摘要結構。
     */
    private toBetHistorySummary(item: SlotApiBetHistoryItem): BetHistorySummary {
        return {
            operationId: item.operation_id,
            gameCode: item.game_code,
            currency: item.currency,
            betAmount: item.bet_amount,
            winAmount: item.win_amount,
            rawEngineWin: item.raw_engine_win ?? item.win_amount,
            engineWin: item.engine_win ?? item.win_amount,
            profit: item.profit,
            balanceAfter: item.balance_after,
            createdAtMs: item.created_at_ms,
            buyFeature: item.buy_feature ?? false,
            isFreeRound: item.is_free_round ?? false,
            jackpotPayout: item.jackpot_payout,
        };
    }
}
