/** Buffer 在後端每欄資料中的位置。 */
export type SlotGridBufferPlacement = 'start' | 'end';

/** 每欄資料的 row 順序。 */
export type SlotGridRowOrder = 'top-down' | 'bottom-up';

/**
 * 後端 Grid 到共用 canonical Grid 的解碼設定。
 *
 * `sourceRowOrder` 描述後端資料；`presentationRowOrder` 描述 decoder 輸出。
 * Symbol ID 只原樣保留，名稱、種類與美術資源由遊戲自己的 SymbolCatalog 解決。
 */
export interface SlotGridLayout {
    columns: number;
    visibleRows: number;
    /** 不規則輪帶（各欄可視列數不同，例如葫蘆型盤面）才需要設定；省略時每欄一律沿用 visibleRows。 */
    visibleRowsPerColumn?: readonly number[];
    bufferRows: number;
    bufferPlacement: SlotGridBufferPlacement;
    sourceRowOrder: SlotGridRowOrder;
    presentationRowOrder: SlotGridRowOrder;
}

/** 取得指定欄的可視列數：有設定 visibleRowsPerColumn 就用該欄的值，否則 fallback 回統一的 visibleRows。 */
export function getVisibleRowsForColumn(layout: SlotGridLayout, col: number): number {
    return layout.visibleRowsPerColumn?.[col] ?? layout.visibleRows;
}

export interface RawSlotGrid {
    columns: number;
    rows: number;
    cells: readonly (readonly number[])[];
}

export interface SlotColumn {
    readonly index: number;
    readonly symbolIds: readonly number[];
}

/** 已移除 buffer 並轉成指定 row order 的純資料盤面。 */
export interface SlotGrid {
    readonly layout: SlotGridLayout;
    readonly columns: readonly SlotColumn[];
}
