import { GAME_EVENT_ID, GAME_EVENT_TYPE, gameRuntimeEventBus } from '../events/GameRuntimeEventBus';

export default class UserStore {
    /** registry 用的 model 識別字串，對應原本 mobx-keystone @model('store/UserStore') */
    public readonly $modelType = 'store/UserStore';

    private _balance = 0;
    /**
     * 玩家目前餘額。
     *
     * @returns 餘額。
     */
    get balance(): number { return this._balance; }

    /** 保留建構子參數是為了相容 StoreManager 裡 `new UserStore({})` 的舊呼叫方式 */
    constructor(_props?: unknown) {}

    /**
     * 更新餘額並發 USER_BALANCE_CHANGED；跟目前相同時直接略過。
     *
     * @param balance 新的餘額。
     */
    setBalance(balance: number): void {
        if (this._balance === balance) return;
        this._balance = balance;
        gameRuntimeEventBus.emit(GAME_EVENT_TYPE.USER_BALANCE_CHANGED, {
            eventId: GAME_EVENT_ID.USER_BALANCE_CHANGED,
            balance,
        });
    }
}
