import { Component, Node } from 'cc';

/**
 * 取元件的兩支輔助函式：取不到就當場丟錯，不要再寫 `node.getComponent(X)!`。
 *
 * 為什麼不能用 `!`：它只騙得過 TypeScript，執行時拿到的仍然是 null，錯誤會延後到
 * 第一次使用該元件時才爆（例如 `view.show()` 變成 "Cannot read properties of null
 * (reading 'show')"），訊息裡沒有節點名、沒有元件名，指不到真正的原因。
 *
 * 這個專案實際踩過：1003 的 winAnimationView / BonusResultView / buyFeaturePopup /
 * hsTransitionPanel 四支 prefab 是從 1001 複製過來的，資產 uuid 都換發了，但元件的
 * `__type__` 還指著 1001 的同名腳本。1003 執行時 1001 的 bundle 沒載入，那個 class
 * 註冊不到，`getComponent(1003 的 class)` 一律回 null——每次中獎都噴一行
 * `null.show()`，完全看不出跟 prefab 有關。
 *
 * 注意：Cocos 另有一個同名的 decorator `@requireComponent(Mask)`（`cc._decorator`），
 * 是「宣告本元件依賴另一個元件」用的，跟這裡無關，所以這兩支刻意不叫那個名字。
 */

type ComponentCtor<T extends Component> = new (...args: any[]) => T;

function describe<T extends Component>(node: Node, type: ComponentCtor<T>, context: string, scope: string): string {
    return (
        `[${context}] ${scope} "${node.name}" 上找不到 ${type.name}；` +
        `最常見的原因是 prefab 掛的是別款遊戲的同名腳本（複製 prefab 時 __type__ 沒換），其次是元件根本沒掛上`
    );
}

/** 取節點自身的元件，取不到丟錯。`context` 請填呼叫點，會直接出現在錯誤訊息裡。 */
export function mustGetComponent<T extends Component>(node: Node, type: ComponentCtor<T>, context: string): T {
    const comp = node.getComponent(type);
    if (!comp) throw new Error(describe(node, type, context, '節點'));
    return comp;
}

/** 取子節點（含自身）的元件，取不到丟錯。 */
export function mustGetComponentInChildren<T extends Component>(node: Node, type: ComponentCtor<T>, context: string): T {
    const comp = node.getComponentInChildren(type);
    if (!comp) throw new Error(describe(node, type, context, '節點子樹'));
    return comp;
}
