/**
 * RestClient
 *
 * 純原生 fetch 實作的 REST client，取代 axios + axios-retry。
 * - 逾時：用 AbortController，不依賴任何套件。
 * - 重試：簡單的固定/線性延遲重試，5xx 與網路層錯誤才重試，4xx 不重試。
 * - 沒有全域攔截器機制（axios interceptor）；認證 header 等共用邏輯由呼叫端
 *   透過 defaultHeaders / getAuthHeaders 注入，保持單純。
 */
import { Logger } from '../utils/Logger';

export type RestMethod = 'GET' | 'POST' | 'PUT' | 'DELETE' | 'PATCH';

export interface RestClientOptions {
    /** 例如 https://api.example.com；留空則 path 需為完整 URL */
    baseUrl?: string;
    /** 每個請求的預設逾時（毫秒），預設 15000 */
    timeoutMs?: number;
    /** 5xx／網路錯誤的重試次數（不含第一次），預設 0（不重試） */
    retries?: number;
    /** 重試間隔（毫秒），會依重試次數線性遞增：delay * (attempt) */
    retryDelayMs?: number;
    /** 每個請求都會帶上的 header */
    defaultHeaders?: Record<string, string>;
    /** 每次請求前動態取得 header（例如帶最新 token），會與 defaultHeaders 合併（此優先） */
    getAuthHeaders?: () => Record<string, string>;
}

export interface RestRequestOptions {
    method?: RestMethod;
    headers?: Record<string, string>;
    /** query string 參數；undefined 值會被忽略 */
    query?: Record<string, string | number | boolean | undefined>;
    /** 會被 JSON.stringify；GET/DELETE 通常不帶 */
    body?: unknown;
    timeoutMs?: number;
    retries?: number;
    /** 覆寫此次請求重試的延遲間隔（毫秒） */
    retryDelayMs?: number;
}

export class RestClientError extends Error {
    constructor(
        message: string,
        public readonly status?: number,
        public readonly body?: unknown
    ) {
        super(message);
        this.name = 'RestClientError';
    }
}

function buildUrl(base: string, path: string, query?: RestRequestOptions['query']): string {
    const full = /^https?:\/\//.test(path) ? path : `${base.replace(/\/$/, '')}/${path.replace(/^\//, '')}`;
    if (!query) return full;

    const usp = new URLSearchParams();
    for (const key of Object.keys(query)) {
        const value = query[key];
        if (value === undefined) continue;
        usp.append(key, String(value));
    }
    const qs = usp.toString();
    return qs ? `${full}${full.includes('?') ? '&' : '?'}${qs}` : full;
}

function delay(ms: number): Promise<void> {
    return new Promise((resolve) => setTimeout(resolve, ms));
}

export class RestClient {
    /**
     * @param options 基底網址、逾時與重試次數的預設值。
     */
    constructor(private readonly options: RestClientOptions = {}) {}

    /**
     * 送一個 GET 請求。
     *
     * @param path 相對於基底網址的路徑。
     * @param options 查詢參數、header、逾時與重試設定。
     * @returns 解析後的回應內容。
     * @throws 重試用盡後仍失敗時丟 RestClientError。
     */
    public get<T>(path: string, options?: Omit<RestRequestOptions, 'method' | 'body'>): Promise<T> {
        return this.request<T>(path, { ...options, method: 'GET' });
    }

    /**
     * 送一個 POST 請求。
     *
     * @param path 相對於基底網址的路徑。
     * @param body 請求內容，會序列化成 JSON。
     * @param options 查詢參數、header、逾時與重試設定。
     * @returns 解析後的回應內容。
     * @throws 重試用盡後仍失敗時丟 RestClientError。
     */
    public post<T>(path: string, body?: unknown, options?: Omit<RestRequestOptions, 'method' | 'body'>): Promise<T> {
        return this.request<T>(path, { ...options, method: 'POST', body });
    }

    /**
     * 送出請求，失敗時依 isRetryable() 判斷要不要重試。
     *
     * @param path 相對於基底網址的路徑。
     * @param options 方法、內容、查詢參數、逾時與重試設定。
     * @returns 解析後的回應內容。
     * @throws 重試用盡後仍失敗時丟出最後一次的錯誤。
     */
    public async request<T>(path: string, options: RestRequestOptions = {}): Promise<T> {
        const retries = options.retries ?? this.options.retries ?? 0;
        let lastError: unknown;

        for (let attempt = 0; attempt <= retries; attempt++) {
            try {
                return await this.doRequest<T>(path, options);
            } catch (error) {
                lastError = error;
                const shouldRetry = attempt < retries && this.isRetryable(error);
                if (!shouldRetry) throw error;
                const retryDelayMs = options.retryDelayMs ?? this.options.retryDelayMs ?? 300;
                await delay(retryDelayMs * (attempt + 1));
            }
        }
        throw lastError;
    }

    /**
     * 判斷這個錯誤值不值得重試。
     *
     * 沒有 status（網路層失敗或逾時）與 5xx 才重試；4xx 是呼叫端自己的問題，
     * 重試幾次結果都一樣，只會拖長使用者等待。
     *
     * @param error 捕捉到的錯誤。
     * @returns 可以重試時 true。
     */
    private isRetryable(error: unknown): boolean {
        if (error instanceof RestClientError) {
            // 沒有 status（網路層失敗／逾時）或 5xx 才重試；4xx 視為呼叫端問題，不重試
            return error.status === undefined || error.status >= 500;
        }
        return true;
    }

    /**
     * 送出單次請求：組網址、掛逾時中止、解析回應。
     *
     * 逾時用 AbortController 主動中止，不是單純等——`fetch` 本身沒有逾時，
     * 少了這層的話連不上時會 await 到天荒地老。
     *
     * @param path 相對於基底網址的路徑。
     * @param options 這次請求的設定。
     * @returns 解析後的回應內容。
     * @throws 逾時、網路失敗或 HTTP 非 2xx 時丟 RestClientError。
     */
    private async doRequest<T>(path: string, options: RestRequestOptions): Promise<T> {
        const url = buildUrl(this.options.baseUrl ?? '', path, options.query);
        const timeoutMs = options.timeoutMs ?? this.options.timeoutMs ?? 15000;
        const method = options.method ?? 'GET';

        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), timeoutMs);

        const headers: Record<string, string> = {
            ...(method === 'GET' ? {} : { 'Content-Type': 'application/json' }),
            ...this.options.defaultHeaders,
            ...this.options.getAuthHeaders?.(),
            ...options.headers,
        };

        try {
            const requestLog: Record<string, unknown> = {
                method,
                url,
                headers: this.sanitize(headers),
            };
            if (options.body !== undefined) requestLog.body = this.sanitize(options.body);
            console.log('[RestClient][Request]', Logger.fmt(requestLog));
            const response = await globalThis.fetch(url, {
                method,
                headers,
                body: options.body !== undefined ? JSON.stringify(options.body) : undefined,
                signal: controller.signal,
            });

            const text = await response.text();
            const data = text ? this.safeParseJson(text) : undefined;
            console.log('[RestClient][Response]', Logger.fmt({
                method,
                url,
                status: response.status,
                data: this.sanitize(data),
            }));

            if (!response.ok) {
                throw new RestClientError(`RestClient request failed: ${response.status} ${response.statusText}`, response.status, data);
            }
            return data as T;
        } catch (error) {
            if (error instanceof RestClientError) throw error;
            if ((error as { name?: string })?.name === 'AbortError') {
                throw new RestClientError(`RestClient request timeout after ${timeoutMs}ms: ${url}`);
            }
            throw new RestClientError(`RestClient network error: ${String(error)}`);
        } finally {
            clearTimeout(timeoutId);
        }
    }

    /**
     * 盡量把回應解析成 JSON，解不動就原樣回字串。
     *
     * 錯誤回應有時是純文字而不是 JSON，這裡不該為此丟例外——
     * 真正的錯誤資訊要留給上層的 RestClientError 帶出去。
     *
     * @param text 回應內容。
     * @returns 解析後的物件，或原始字串。
     */
    private safeParseJson(text: string): unknown {
        try {
            return JSON.parse(text);
        } catch {
            return text;
        }
    }

    /**
     * 遞迴把敏感欄位（password／token／authorization）換成 [REDACTED]，供寫 log 用。
     *
     * @param value 要處理的值。
     * @returns 遮蔽後的副本；原物件不動。
     */
    private sanitize(value: unknown): unknown {
        if (Array.isArray(value)) return value.map((item) => this.sanitize(item));
        if (!value || typeof value !== 'object') return value;

        const result: Record<string, unknown> = {};
        for (const [key, item] of Object.entries(value as Record<string, unknown>)) {
            result[key] = /password|token|authorization/i.test(key) ? '[REDACTED]' : this.sanitize(item);
        }
        return result;
    }
}
