import { _decorator, sp } from 'cc';
import { SymbolView } from './SymbolView';
import { trySetAnimation, tryClearAnimation } from '../../utils/SpineSafe';

const { ccclass, property } = _decorator;

/**
 * Spine 版的顯示層：租出去時播一段動畫，回收時清掉軌道。
 *
 * 設計依據：entry repo `docs/SlotSymbolSystem_設計參考.md` §6（顯示技術轉接器）。
 * 邏輯層完全感覺不到自己租到的是 Sprite 版還是這一版。
 *
 * 用在 `WinAnimation`（`symbol_win` 火焰框）、`Erase`（`symbol_frame` 爆破）、以及素材到位後的
 * `symbol_h`／`symbol_l` 符號動畫。
 */
@ccclass('1003/SymbolViewSpine')
export class SymbolViewSpine extends SymbolView {
    @property({ type: sp.Skeleton, tooltip: '實際播動畫的 Skeleton；留空時這顆物件等同靜態圖' })
    public skeleton: sp.Skeleton = null!;

    @property({ tooltip: '租借時要播的動畫名稱' })
    public animName: string = 'animation';

    @property({ tooltip: '是否循環播放。中獎中的常駐演出勾起來，一次性爆破不要勾' })
    public loop: boolean = false;

    /**
     * 每個符號的動畫名稱可能不同（例如 `symbol_h` 這份骨架裡 h1 叫 `God`、h2 叫 `h2`），
     * 所以租借時允許外部指定；沒指定就用 {@link animName}。
     */
    private overrideAnim: string | null = null;

    /**
     * 指定這次租借要播的動畫，必須在 {@link onRent} 之前呼叫。
     *
     * @param anim 動畫名稱；傳 null 表示改用 prefab 上設定的 {@link animName}。
     */
    public setAnimOverride(anim: string | null): void {
        this.overrideAnim = anim;
    }

    /** 建立當下先把軌道清乾淨，避免 prefab 存檔時殘留的預設動畫在節點一開就播出來 */
    protected override onInit(): void {
        if (this.skeleton) tryClearAnimation(this.skeleton, 'SymbolViewSpine.onInit');
    }

    /** 歸還：停掉動畫並清空軌道，否則下次租出去會先閃一格上一次的最後畫面 */
    public override onReturn(): void {
        if (this.skeleton?.isValid) {
            this.skeleton.setCompleteListener(null!);
            tryClearAnimation(this.skeleton, 'SymbolViewSpine.onReturn');
        }
        this.overrideAnim = null;
        super.onReturn();
    }

    /** 從頭重播。動畫名不存在時 {@link trySetAnimation} 會吞掉例外並警告一次，不會中斷整條流程 */
    public override resetAni(): void {
        if (!this.skeleton) return;
        const anim = this.overrideAnim ?? this.animName;
        this.skeleton.timeScale = 1;
        trySetAnimation(this.skeleton, anim, this.loop, 'SymbolViewSpine.resetAni');
    }

    /**
     * 播一次並在結束時回呼。
     *
     * 只在 `trackIndex === 0` 時回呼，避免其他軌道的結束事件誤觸。沒有 skeleton 時立刻回呼，
     * 行為與基底一致。
     *
     * @param onComplete 播完時呼叫。
     */
    public override playOnce(onComplete: () => void): void {
        if (!this.skeleton) {
            onComplete();
            return;
        }
        const anim = this.overrideAnim ?? this.animName;
        this.skeleton.setCompleteListener((entry) => {
            if (entry.trackIndex !== 0) return;
            this.skeleton.setCompleteListener(null!);
            onComplete();
        });
        trySetAnimation(this.skeleton, anim, false, 'SymbolViewSpine.playOnce');
    }

    /**
     * 調整播放速度，供三段速（一般／快速／turbo）縮放演出時長用。
     *
     * @param scale 倍率，1 為原速。
     */
    public override setTimeScale(scale: number): void {
        if (this.skeleton) this.skeleton.timeScale = scale;
    }
}
