import { LoadingView } from "./LoadingView";
import LoadingModel from "./LoadingModel";
import StoreManager from '../../store/StoreManager';
import { GAME_EVENT_TYPE, gameRuntimeEventBus } from '../../events/GameRuntimeEventBus';
export default class LoadingViewModel {

    loadingView: LoadingView
    loadingStore: LoadingModel
    storeManager: StoreManager
    /**
     * 移除 HTML 那層的預載畫面，建立 LoadingModel 並訂閱進度事件。
     *
     * @param context 要操作的 Loading 畫面。
     */
    constructor(context: LoadingView) {
        this.loadingView = context;
        if (typeof document !== "undefined") document.getElementById("bg-loading")?.remove?.();
        this.registerLoadingModel();
        this.registerReactions();
    }
    /**
     * 建立 LoadingModel 並註冊進 StoreManager。
     */
    registerLoadingModel() {
        this.storeManager = StoreManager.getInstance();
        this.loadingStore = new LoadingModel({});
        this.storeManager.registerModel(this.loadingStore);
    }

    /**
     * 訂閱載入進度與方向變化，並立刻補跑一次目前的值。
     *
     * 補跑那一次等效原本 mobx reaction 的 `fireImmediately: true`。
     */
    registerReactions() {
        // mobx 移除計劃：LoadingModel.progress/DeviceStore.orientation 已改由 gameRuntimeEventBus 通知，不再用 mobx reaction
        this.loadingView.subscribeGameEvent(gameRuntimeEventBus, GAME_EVENT_TYPE.LOADING_PROGRESS_CHANGED,
            (e) => this.loadingView.updateProgress(e.progress));
        this.loadingView.updateProgress(this.loadingStore.progress); // 等效原本的 fireImmediately: true

        this.loadingView.subscribeGameEvent(gameRuntimeEventBus, GAME_EVENT_TYPE.DEVICE_ORIENTATION_CHANGED,
            (e) => this.loadingView.checkPosition(e.orientation));
        this.loadingView.checkPosition(this.storeManager.getDeviceStore()?.orientation); // 等效原本沒指定 fireImmediately 時的預設 true
    }
}