import type { Node } from 'cc';
import GameConfigManager from '../../config/GameConfigManager';
import { ORIENTATION } from '../../store/StoreMap';
import { HistoryView } from '../PopupView/History/HistoryView';
import StoreManager from '../../store/StoreManager';
import { HistoryItem } from '../PopupView/History/HistoryItem';
export default class HistoryModel {
    view: HistoryView;
    storeManager: StoreManager;
    infoData: null;
    /**
     * @param context 要操作的歷史紀錄 View。
     */
    constructor(context: HistoryView) {
        this.view = context;
        this.storeManager = StoreManager.getInstance();
    }
    /**
     * 把 store 裡的投注紀錄逐筆建成清單項目；沒有紀錄時什麼都不做。
     *
     * @returns 全部建好之後 resolve。
     */
    async addHistoryItem() {
        const historyPage = this.storeManager.getGameStore().historyData;
        const items = historyPage?.items ?? [];
        if (items.length === 0) return;
        items.forEach((history) => {
            if (this.storeManager.getGameStore().roundId === history.operationId) return;
            let item = this.view.addHistoryItem(this.storeManager.getDeviceStore().orientation);
            let itemTS = item.getComponent(HistoryItem);
            itemTS.titleData = history;
            itemTS.historyView = this.view;
        });
    }

    /**
     * 向後端要單筆明細並用遊戲自己的 adapter 組出盤面節點。
     *
     * @param operationId 該筆紀錄的操作 id。
     * @returns 明細節點；拿不到資料時是 null。
     */
    async createHistoryDetailView(operationId: string): Promise<Node | null> {
        const data = await this.storeManager.getHttpClientStore()?.getHistoryDetail?.(operationId);
        if (!data) return null;

        const GameAdapter = await this.loadGameAdapter();
        const gameAdapter = new GameAdapter();
        const isPortrait = this.storeManager.getDeviceStore().orientation !== ORIENTATION.LANDSCAPE;
        return gameAdapter.getRoundDetail(data, isPortrait);
    }

    /**
     * 取得歷史明細的 adapter。
     *
     * 這個 bundle 只帶巨亨麻將自己那支——原本 entry 的版本是用 GAMEID 分支動態 import
     * 別款遊戲的 adapter，在獨立 bundle 裡不能這樣做（跨 gameId 相依）。
     *
     * @returns 巨亨麻將的 HistoryAdapter 類別。
     */
    private async loadGameAdapter() {
        return (await import('./HistoryAdapter')).default;
    }
}
