/**
 * 直橫版切換 —「顯示/渲染」層面：決定當下哪一個 view（viewH/viewV）真正被看到。
 * viewH/viewV 兩棵節點樹同時存在場景裡，靠 Cocos layer 過濾 + camera.visibility
 * 讓非當前方向的子樹完全不被渲染，並關掉其 spine/particle 省效能，屬於二選一的顯示開關。
 *
 * 跟 DualViewController 的差異：DualViewController 管的是「資料同步」——寫入操作要不要
 * 同時作用在兩個 view 上；這裡管的是「哪一個 view 現在真正顯示出來」。兩者互補：
 * 遊戲邏輯透過 DualViewController 讓兩邊狀態隨時保持同步，OrientationController 再決定
 * 當下要把哪一邊呈現給玩家看，切換時另一邊已經是同步好的正確狀態，不用重建。
 */
import { Camera, Layers, Node, ParticleSystem2D, sp, Vec3 } from "cc";

/** OrientationController 只需要用到的 View 子集合，各遊戲自己的 GameViewAdapter 結構相容即可傳入 */
export interface OrientationView {
    node: Node;
    chestRed?: sp.Skeleton | null;
    chestGreen?: sp.Skeleton | null;
    chestBlue?: sp.Skeleton | null;
    commonFxRed?: sp.Skeleton | null;
    commonFxGreen?: sp.Skeleton | null;
    commonFxBlue?: sp.Skeleton | null;
    buyRandomFlashSpine?: sp.Skeleton | null;
    buySuperFlashSpine?: sp.Skeleton | null;
}

export interface OrientationDeps {
    getViewH: () => OrientationView;
    getViewV: () => OrientationView | null;
    getMainCamera: () => Camera | null;
}

const VIEW_H_LAYER = 1 << 4; // 16
const VIEW_V_LAYER = 1 << 5; // 32
const BASE_VISIBILITY = Layers.Enum.UI_2D | Layers.Enum.UI_3D | Layers.Enum.DEFAULT | Layers.Enum.IGNORE_RAYCAST;

/**
 * 直橫版切換：透過 layer 過濾，讓非當前方向的子樹完全不被 camera 渲染。
 * 1001/1002 邏輯完全相同。
 */
export class OrientationController {
    /**
     * @param deps 取得橫直版 View 與主攝影機的依賴。
     */
    constructor(private deps: OrientationDeps) { }

    /** 初始化：套用當前方向 + 掛上「新增子節點自動繼承當前 layer」的追蹤 */
    init(isLandscape: boolean): void {
        this.applyOrientation(isLandscape);
        this.trackChildren(this.deps.getViewH().node, () => VIEW_H_LAYER);
        const viewV = this.deps.getViewV();
        if (viewV) this.trackChildren(viewV.node, () => VIEW_V_LAYER);
    }

    /**
     * 套用螢幕方向：把不顯示的那一份 View 移到畫面外，並關掉它底下的 spine 與粒子。
     *
     * 移到 x = 9999 而不是設 active = false，是因為兩份都要持續收事件更新數字；
     * 但它們的動畫要關掉，不然背景那份會白白吃掉效能。
     *
     * @param isLandscape 是否為橫版。
     */
    applyOrientation(isLandscape: boolean): void {
        const viewH = this.deps.getViewH();
        const viewV = this.deps.getViewV();

        viewH.node.setPosition(new Vec3(isLandscape ? 0 : 9999, 0, 0));
        if (viewV) viewV.node.setPosition(new Vec3(isLandscape ? 9999 : 0, 0, 0));

        this.setLayerRecursive(viewH.node, VIEW_H_LAYER);
        if (viewV) this.setLayerRecursive(viewV.node, VIEW_V_LAYER);

        this.setAllSpinesEnabled(viewH, isLandscape);
        this.setAllSpinesEnabled(viewV, !isLandscape);
        this.setAllParticlesEnabled(viewH, isLandscape);
        this.setAllParticlesEnabled(viewV, !isLandscape);

        const camera = this.deps.getMainCamera();
        if (camera) {
            camera.visibility = BASE_VISIBILITY | (isLandscape ? VIEW_H_LAYER : VIEW_V_LAYER);
        }
    }

    /**
     * 遞迴把節點與其子節點的 layer 設成指定值。
     *
     * @param node 起點節點。
     * @param layer 要套用的 layer。
     */
    private setLayerRecursive(node: Node, layer: number): void {
        node.layer = layer;
        const children = node.children;
        for (let i = 0; i < children.length; i++) this.setLayerRecursive(children[i], layer);
    }

    // 新增子節點時自動繼承當前 layer：每個節點都掛 listener，新進子樹也遞迴掛
    private trackChildren(root: Node, getLayer: () => number): void {
        const attach = (n: Node): void => {
            n.on(Node.EventType.CHILD_ADDED, (child: Node) => {
                this.setLayerRecursive(child, getLayer());
                attach(child);
            });
            const cs = n.children;
            for (let i = 0; i < cs.length; i++) attach(cs[i]);
        };
        attach(root);
    }

    // 隱藏方向的 view：spine 都關，但**排除 listener 驅動的**（寶箱、buyFeature flash）。
    // 否則 enabled=false 會讓 setCompleteListener 不觸發，
    // 例如直版 bonus 寶箱長大會卡到一半。
    /**
     * 開關某一份 View 底下所有 spine，但排除幾個需要保持狀態的（寶箱、共用特效）。
     *
     * 那幾個排除的 spine 在切換方向時如果被停掉，回來會從頭開始播，
     * 跟另一份的播放進度對不起來。
     *
     * @param view 目標 View；null 時直接返回。
     * @param enabled 要開還是要關。
     */
    private setAllSpinesEnabled(view: OrientationView | null, enabled: boolean): void {
        if (!view) return;
        const exclude = new Set<sp.Skeleton>([view.chestRed, view.chestGreen, view.chestBlue, view.commonFxRed, view.commonFxGreen, view.commonFxBlue, view.buyRandomFlashSpine, view.buySuperFlashSpine].filter(Boolean));
        const skels = view.node.getComponentsInChildren(sp.Skeleton);
        for (let i = 0; i < skels.length; i++) {
            if (exclude.has(skels[i])) continue;
            skels[i].enabled = enabled;
        }
    }

    // 隱藏方向的 view：ParticleSystem2D（fire_star、fog 等背景粒子）也關
    /**
     * 開關某一份 View 底下所有 2D 粒子。
     *
     * @param view 目標 View；null 時直接返回。
     * @param enabled 要開還是要關。
     */
    private setAllParticlesEnabled(view: OrientationView | null, enabled: boolean): void {
        if (!view) return;
        const particles = view.node.getComponentsInChildren(ParticleSystem2D);
        for (let i = 0; i < particles.length; i++) {
            particles[i].enabled = enabled;
        }
    }
}
